<h1><?= te('Private document proofs') ?></h1><p class="sub"><?= te('Upload evidence for office review. A proof upload alone does not complete I-9 verification or tax-form processing.') ?></p><?php if(!$configured): ?><div class="flash err"><?= te('An encryption key must be configured before documents can be uploaded or downloaded.') ?></div><?php endif; ?><?php if($configured): ?><form class="card" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="do" value="upload"><?php if(!$isWorker): ?><label for="pf-who"><?= te('Whose document') ?></label><select id="pf-who" name="candidate_id" required><option value=""><?= te('Choose somebody…') ?></option><?php foreach($people as $person): ?><option value="<?= (int)$person['id'] ?>"><?= e($person['full_name']) ?></option><?php endforeach; ?></select><?php endif; ?><label><?= te('Document type / purpose') ?></label><input name="document_type" required maxlength="120"><label><?= te('PDF, JPEG or PNG · maximum 10 MB') ?></label><input type="file" name="proof" accept="application/pdf,image/jpeg,image/png" required><button class="btn"><?= te('Upload securely') ?></button></form><?php endif; ?><?php if(!$documents): ?><div class="card"><div class="empty"><?= te('No documents uploaded yet. A proof arrives when somebody uploads one here or from their private portal.') ?></div></div><?php endif; ?><?php foreach($documents as $d): ?><div class="card"><div class="page-heading" style="margin:0 0 10px"><div><h2 style="margin:0"><?= e($d['full_name'] ?? t('Unknown person')) ?></h2><p class="small muted" style="margin:4px 0 0"><?= e($d['document_type']) ?> &middot; <?= te('uploaded :when', ['when' => d($d['created_at'])]) ?></p></div><span class="tag <?= $d['status']==='approved'?'green':($d['status']==='rejected'?'red':'amber') ?>"><?= te(ucfirst((string)$d['status'])) ?></span></div><?php if(trim((string)$d['review_note'])!==''): ?><p class="small"><?= e($d['review_note']) ?></p><?php endif; ?><a href="/proofs?download=<?= (int)$d['id'] ?>"><?= te('Download proof') ?></a><?php if(!$isWorker): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="review"><input type="hidden" name="document_id" value="<?= (int)$d['id'] ?>"><select name="status"><option value="approved"><?= te('approved') ?></option><option value="rejected"><?= te('rejected') ?></option></select><input name="review_note" placeholder="<?= te('Review note') ?>"><button class="btn"><?= te('Review') ?></button></form><?php endif; ?></div><?php endforeach; ?>